class SettingsViewModel {
  @observable theme: string;
  @observable volume: number;
  @observable notificationsEnabled: boolean;

  constructor(private model: Settings) {
    this.theme = model.theme;
    this.volume = model.volume;
    this.notificationsEnabled = model.notificationsEnabled;
  }
}

// Declarative binding — the framework keeps the UI in sync automatically
